//! RSA private keys and signatures (#175): keys and signatures generated by `openssl`
//! (tests/vectors/rsa), PKCS#1 v1.5 compared byte for byte (it is deterministic), PSS
//! verified in both directions, and our signatures verified by the `openssl` CLI when present.
use kr_crypto::rsa::{HashAlg, PrivateKey};
use kr_crypto::x509::{self, SigningKey};
use std::io::Read;
use std::process::Command;

macro_rules! v {
    ($f:literal) => {
        &include_bytes!(concat!("vectors/rsa/", $f))[..]
    };
}

fn rng(buf: &mut [u8]) {
    std::fs::File::open("/dev/urandom").unwrap().read_exact(buf).unwrap();
}

fn der(pem: &[u8], label: &str) -> Vec<u8> {
    x509::pem_decode_all(std::str::from_utf8(pem).unwrap(), label).unwrap().remove(0)
}

fn pkcs1(pem: &[u8]) -> PrivateKey {
    PrivateKey::from_pkcs1(&der(pem, "RSA PRIVATE KEY")).expect("pkcs1 key")
}

const MSG: &[u8] = include_bytes!("vectors/rsa/msg.bin");

#[test]
fn pkcs1_v15_matches_openssl_byte_for_byte() {
    let cases: [(&[u8], &[u8], HashAlg); 4] = [
        (v!("k1024.pem"), v!("k1024.pkcs1.sha256.sig"), HashAlg::Sha256),
        (v!("k2048.pem"), v!("k2048.pkcs1.sha256.sig"), HashAlg::Sha256),
        (v!("k2048.pem"), v!("k2048.pkcs1.sha384.sig"), HashAlg::Sha384),
        (v!("k3072.pem"), v!("k3072.pkcs1.sha256.sig"), HashAlg::Sha256),
    ];
    for (key, sig, hash) in cases {
        let k = pkcs1(key);
        let ours = k.sign_pkcs1v15(hash, MSG, &mut rng).unwrap();
        assert_eq!(ours, sig);
        assert!(k.public().verify_pkcs1v15(hash, MSG, &ours));
        assert!(!k.public().verify_pkcs1v15(hash, b"other", &ours));
    }
}

#[test]
fn pss_both_directions() {
    for (key, sig) in [(v!("k1024.pem"), v!("k1024.pss.sha256.sig")), (v!("k2048.pem"), v!("k2048.pss.sha256.sig")), (v!("k3072.pem"), v!("k3072.pss.sha256.sig"))] {
        let k = pkcs1(key);
        assert!(k.public().verify_pss(HashAlg::Sha256, MSG, sig, 32), "openssl PSS signature rejected");
        let a = k.sign_pss(HashAlg::Sha256, MSG, 32, &mut rng).unwrap();
        let b = k.sign_pss(HashAlg::Sha256, MSG, 32, &mut rng).unwrap();
        assert_ne!(a, b, "salt must be random");
        for s in [&a, &b] {
            assert!(k.public().verify_pss(HashAlg::Sha256, MSG, s, 32));
            assert!(!k.public().verify_pss(HashAlg::Sha256, b"other", s, 32));
        }
        if let Some(c) = k.sign_pss(HashAlg::Sha512, MSG, 64, &mut rng) {
            assert!(k.public().verify_pss(HashAlg::Sha512, MSG, &c, 64));
        }
    }
}

#[test]
fn pkcs8_and_pkcs1_agree() {
    for (a, b) in [(v!("k2048.pem"), v!("k2048-pkcs8.pem")), (v!("k3072.pem"), v!("k3072-pkcs8.pem"))] {
        let SigningKey::Rsa(p8) = x509::private_key_from_pkcs8(&der(b, "PRIVATE KEY")).unwrap() else { panic!("not RSA") };
        let p1 = pkcs1(a);
        assert_eq!(p8.public(), p1.public());
        assert_eq!(p8.sign_pkcs1v15(HashAlg::Sha256, MSG, &mut rng), p1.sign_pkcs1v15(HashAlg::Sha256, MSG, &mut rng));
    }
    let k = x509::private_key_from_pkcs1(&der(v!("k2048.pem"), "RSA PRIVATE KEY")).unwrap();
    assert!(matches!(k.public(), x509::PublicKey::Rsa(_)));
    assert_eq!(k.sign(MSG), v!("k2048.pkcs1.sha256.sig"));
}

#[test]
fn damaged_keys_are_refused() {
    let good = der(v!("k2048.pem"), "RSA PRIVATE KEY");
    assert!(PrivateKey::from_pkcs1(&good).is_some());
    for pos in [20usize, 300, 400, 600, 800, 1000, 1100, 1190] {
        let mut bad = good.clone();
        bad[pos] ^= 0x40;
        if let Some(k) = PrivateKey::from_pkcs1(&bad) {
            // Parsed (the flip hit d or a CRT exponent): signing either stays right or the
            // fault check refuses it; a wrong signature is never released.
            if let Some(sig) = k.sign_pkcs1v15(HashAlg::Sha256, MSG, &mut rng) {
                assert_eq!(sig, v!("k2048.pkcs1.sha256.sig"), "pos {pos}");
            }
        }
    }
    assert!(PrivateKey::from_pkcs1(&good[..good.len() - 1]).is_none());
    assert!(PrivateKey::from_pkcs1(&[0x30, 0x00]).is_none());
}

#[test]
fn openssl_verifies_our_signatures() {
    if Command::new("openssl").arg("version").output().is_err() {
        return;
    }
    let dir = std::env::temp_dir().join(format!("kr-rsa-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let k = pkcs1(v!("k2048.pem"));
    std::fs::write(dir.join("pub.pem"), v!("k2048.pub.pem")).unwrap();
    std::fs::write(dir.join("msg"), MSG).unwrap();
    for pss in [false, true] {
        let sig = if pss { k.sign_pss(HashAlg::Sha256, MSG, 32, &mut rng) } else { k.sign_pkcs1v15(HashAlg::Sha256, MSG, &mut rng) }.unwrap();
        std::fs::write(dir.join("sig"), &sig).unwrap();
        let mut c = Command::new("openssl");
        c.args(["dgst", "-sha256", "-verify"]).arg(dir.join("pub.pem")).arg("-signature").arg(dir.join("sig"));
        if pss {
            c.args(["-sigopt", "rsa_padding_mode:pss", "-sigopt", "rsa_pss_saltlen:32"]);
        }
        let out = c.arg(dir.join("msg")).output().unwrap();
        assert!(out.status.success(), "pss={pss}: {}", String::from_utf8_lossy(&out.stderr));
    }
    std::fs::remove_dir_all(&dir).ok();
}
